<?php
require dirname(__DIR__) . '/config.php';
if (isset($_GET['logout'])) { unset($_SESSION['voidloot_admin']); header('Location: index.php'); exit; }
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['login'])) {
    if (hash_equals(admin_password(), $_POST['password'] ?? '')) { $_SESSION['voidloot_admin']=true; header('Location: index.php'); exit; }
    $error='Incorrect password.';
}
if (!is_admin()):
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VOIDLOOT Admin</title><link rel="stylesheet" href="../style.css"></head><body><main class="login-wrap panel"><a class="logo" href="../index.php">VOID<span>LOOT</span></a><h1>ADMIN ACCESS</h1><p class="muted">Sign in to manage the game database.</p><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><form method="post"><input type="password" name="password" placeholder="Admin password" required><button class="btn primary" name="login" value="1">Enter control room</button></form></main></body></html><?php exit; endif;
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_game'])) {
    verify_csrf();
    $gameId=(int)($_POST['id']??0);
    $data=[trim($_POST['title']??''),trim($_POST['tagline']??''),trim($_POST['description']??''),safe_url($_POST['cover_url']??''),safe_url($_POST['banner_url']??''),safe_url($_POST['trailer_url']??''),trim($_POST['developer']??''),trim($_POST['publisher']??''),trim($_POST['genre']??''),trim($_POST['release_date']??''),(int)!empty($_POST['featured'])];
    if($gameId){$q=db()->prepare("UPDATE games SET title=?,tagline=?,description=?,cover_url=?,banner_url=?,trailer_url=?,developer=?,publisher=?,genre=?,release_date=?,featured=? WHERE id=?");$q->execute([...$data,$gameId]);}
    else {$q=db()->prepare("INSERT INTO games(title,tagline,description,cover_url,banner_url,trailer_url,developer,publisher,genre,release_date,featured) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$q->execute($data);$gameId=(int)db()->lastInsertId();}
    foreach(['minimum','recommended'] as $kind){$fields=[];foreach(['os','processor','memory','graphics','directx','storage'] as $f)$fields[$f]=trim($_POST[$kind.'_'.$f]??'');$q=db()->prepare("INSERT INTO game_requirements(game_id,kind,os,processor,memory,graphics,directx,storage) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE os=VALUES(os),processor=VALUES(processor),memory=VALUES(memory),graphics=VALUES(graphics),directx=VALUES(directx),storage=VALUES(storage)");$q->execute([$gameId,$kind,...array_values($fields)]);}
    foreach(['screenshots'=>'game_screenshots','sources'=>'game_sources'] as $key=>$table){db()->prepare("DELETE FROM $table WHERE game_id=?")->execute([$gameId]);$lines=preg_split('/\R/',trim($_POST[$key]??''));foreach($lines as $line){if(!$line)continue;$parts=array_map('trim',explode('|',$line,2));if(count($parts)<2)continue;if($key==='screenshots'){$u=safe_url($parts[0]);if($u)db()->prepare("INSERT INTO game_screenshots(game_id,image_url) VALUES(?,?)")->execute([$gameId,$u]);}else{$u=safe_url($parts[1]);if($u)db()->prepare("INSERT INTO game_sources(game_id,source_name,source_url) VALUES(?,?,?)")->execute([$gameId,$parts[0],$u]);}}}
    header('Location: index.php?saved=1');exit;
}
if(isset($_GET['delete'])){ $id=(int)$_GET['delete']; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare("DELETE FROM games WHERE id=?")->execute([$id]);header('Location: index.php');exit;} }
$edit=null;$requirements=[];$screens='';$sources='';
if(isset($_GET['edit'])){$q=db()->prepare("SELECT * FROM games WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();if($edit){$q=db()->prepare("SELECT * FROM game_requirements WHERE game_id=?");$q->execute([$edit['id']]);foreach($q as $r)$requirements[$r['kind']]=$r;$q=db()->prepare("SELECT image_url FROM game_screenshots WHERE game_id=?");$q->execute([$edit['id']]);$screens=implode("\n",$q->fetchAll(PDO::FETCH_COLUMN));$q=db()->prepare("SELECT source_name,source_url FROM game_sources WHERE game_id=?");$q->execute([$edit['id']]);$sources=implode("\n",array_map(fn($r)=>$r['source_name'].' | '.$r['source_url'],$q->fetchAll()));}}
$games=db()->query("SELECT id,title,genre FROM games ORDER BY title")->fetchAll();
function val($a,$k){return e($a[$k]??'');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VOIDLOOT Control Room</title><link rel="stylesheet" href="../style.css"></head><body><header class="topbar"><a class="logo" href="../index.php">VOID<span>LOOT</span></a><nav><a href="../index.php">View site</a><a href="?logout=1">Logout</a></nav></header><main class="admin-shell"><div class="section-head"><div><span class="eyebrow">CONTROL ROOM</span><h1>Manage games</h1></div><a class="btn" href="index.php">New game</a></div><?php if(isset($_GET['saved'])):?><p class="success">Game saved successfully.</p><?php endif; ?><div class="admin-grid"><form class="panel admin-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><h2><?= $edit?'Edit game':'Add a game' ?></h2><label>Game title<input name="title" required value="<?=val($edit??[],'title')?>"></label><label>Tagline<input name="tagline" value="<?=val($edit??[],'tagline')?>"></label><label>Description<textarea name="description" rows="5"><?=val($edit??[],'description')?></textarea></label><div class="form-two"><label>Cover image URL<input name="cover_url" value="<?=val($edit??[],'cover_url')?>"></label><label>Banner image URL<input name="banner_url" value="<?=val($edit??[],'banner_url')?>"></label><label>Gameplay trailer URL<input name="trailer_url" value="<?=val($edit??[],'trailer_url')?>"></label><label>Developer<input name="developer" value="<?=val($edit??[],'developer')?>"></label><label>Publisher<input name="publisher" value="<?=val($edit??[],'publisher')?>"></label><label>Genre<input name="genre" value="<?=val($edit??[],'genre')?>"></label><label>Release date<input name="release_date" placeholder="YYYY-MM-DD" value="<?=val($edit??[],'release_date')?>"></label></div><label class="check"><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Feature this game on homepage</label><h3>Media and official sources</h3><label>Screenshots, one image URL per line<textarea name="screenshots" rows="3"><?=e($screens)?></textarea></label><label>Download sources, one per line: Source name | https://official-url<textarea name="sources" rows="4"><?=e($sources)?></textarea></label><h3>Minimum requirements</h3><?php foreach(['os'=>'Operating system','processor'=>'Processor','memory'=>'Memory','graphics'=>'Graphics','directx'=>'DirectX','storage'=>'Storage'] as $f=>$n): ?><label><?=$n?><input name="minimum_<?=$f?>" value="<?=val($requirements['minimum']??[],$f)?>"></label><?php endforeach; ?><h3>Recommended requirements</h3><?php foreach(['os'=>'Operating system','processor'=>'Processor','memory'=>'Memory','graphics'=>'Graphics','directx'=>'DirectX','storage'=>'Storage'] as $f=>$n): ?><label><?=$n?><input name="recommended_<?=$f?>" value="<?=val($requirements['recommended']??[],$f)?>"></label><?php endforeach; ?><button class="btn primary" name="save_game" value="1">Save game</button></form><aside class="panel"><h2>Game library</h2><?php foreach($games as $g): ?><div class="admin-game"><div><b><?=e($g['title'])?></b><small><?=e($g['genre'])?></small></div><a href="?edit=<?=$g['id']?>">Edit</a></div><?php endforeach; ?></aside></div></main></body></html>
